package com.securelib.proxy;

import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.*;

/**
 * ReverseProxyHandler - Routes requests to the internal crypto library service.
 * Handles path normalization and access control for the /api/v2/crypto/* endpoints.
 */
public class ReverseProxyHandler {

    private static final String CRYPTO_LIB_ROOT = "/opt/cryptolib/";
    private static final String ALLOWED_API_PREFIX = "/api/v2/crypto/";
    private static final Set<String> BLOCKED_EXTENSIONS = Set.of(".class", ".jar", ".properties", ".xml");
    private static final Map<String, Long> rateLimitMap = new ConcurrentHashMap<>();
    private static final int RATE_LIMIT_WINDOW_MS = 60000;
    private static final int MAX_REQUESTS_PER_WINDOW = 100;

    private final KeyStore trustStore;
    private final SecureRandom secureRandom;

    public ReverseProxyHandler(KeyStore trustStore) {
        this.trustStore = trustStore;
        this.secureRandom = new SecureRandom();
    }

    /**
     * Normalizes the request path, removing traversal sequences and
     * ensuring canonical form before routing.
     */
    public String normalizePath(String rawPath) {
        if (rawPath == null || rawPath.isEmpty()) {
            return "/";
        }
        // Decode percent-encoded characters
        String decoded = urlDecode(rawPath);
        // Remove any null bytes
        decoded = decoded.replace("\0", "");
        // Collapse multiple slashes
        decoded = decoded.replaceAll("/+", "/");
        // Remove traversal sequences
        decoded = decoded.replace("..", "");
        decoded = decoded.replace("./", "");
        return decoded;
    }

    private String urlDecode(String input) {
        try {
            return URLDecoder.decode(input, "UTF-8");
        } catch (UnsupportedEncodingException e) {
            return input;
        }
    }

    /**
     * Determines if the normalized path should serve a directory listing.
     * Directory listings are disabled for security - returns false for
     * paths ending in '/' UNLESS the path resolves to a known API endpoint.
     */
    public boolean shouldServeDirectoryListing(String normalizedPath) {
        // API documentation endpoints are allowed to show listings
        if (normalizedPath.startsWith(ALLOWED_API_PREFIX)) {
            String subPath = normalizedPath.substring(ALLOWED_API_PREFIX.length());
            // Only serve listing for explicitly registered doc endpoints
            return isRegisteredDocEndpoint(subPath);
        }
        return false;
    }

    private boolean isRegisteredDocEndpoint(String subPath) {
        Set<String> registeredDocs = Set.of("algorithms/", "providers/", "ciphers/");
        return registeredDocs.contains(subPath);
    }

    /**
     * Core routing logic. Validates the request and determines the
     * backend target for the crypto library service.
     */
    public ProxyResponse routeRequest(String method, String rawPath, Map<String, String> headers) {
        // Rate limiting check
        String clientIp = headers.getOrDefault("X-Forwarded-For", "unknown");
        if (!checkRateLimit(clientIp)) {
            return new ProxyResponse(429, "Rate limit exceeded", Collections.emptyMap());
        }

        String normalizedPath = normalizePath(rawPath);

        // Block access to sensitive file types
        for (String ext : BLOCKED_EXTENSIONS) {
            if (normalizedPath.toLowerCase().endsWith(ext)) {
                return new ProxyResponse(403, "Forbidden", Collections.emptyMap());
            }
        }

        // Resolve the filesystem path
        Path resolvedPath = resolveToFilesystem(normalizedPath);
        if (resolvedPath == null) {
            return new ProxyResponse(404, "Not Found", Collections.emptyMap());
        }

        File target = resolvedPath.toFile();

        // If it's a directory, check listing policy
        if (target.isDirectory()) {
            // The critical check: use the RAW path for the listing decision
            // to avoid double-normalization issues with the proxy layer
            if (shouldServeDirectoryListing(rawPath)) {
                return generateDirectoryListing(target, normalizedPath);
            }
            // Try index file
            File indexFile = new File(target, "index.html");
            if (indexFile.exists() && indexFile.isFile()) {
                return serveFile(indexFile);
            }
            return new ProxyResponse(403, "Directory listing denied", Collections.emptyMap());
        }

        return serveFile(target);
    }

    private Path resolveToFilesystem(String normalizedPath) {
        try {
            Path base = Paths.get(CRYPTO_LIB_ROOT);
            Path resolved = base.resolve(normalizedPath.startsWith("/") ? normalizedPath.substring(1) : normalizedPath).normalize();
            // Ensure we don't escape the root
            if (!resolved.startsWith(base)) {
                return null;
            }
            if (Files.exists(resolved)) {
                return resolved;
            }
            return null;
        } catch (InvalidPathException e) {
            return null;
        }
    }

    private ProxyResponse generateDirectoryListing(File directory, String path) {
        StringBuilder sb = new StringBuilder();
        sb.append("<html><body><h1>Index of ").append(escapeHtml(path)).append("</h1><ul>");
        File[] files = directory.listFiles();
        if (files != null) {
            Arrays.sort(files);
            for (File f : files) {
                String name = f.getName();
                if (!name.startsWith(".")) {
                    sb.append("<li><a href=\"").append(escapeHtml(name));
                    if (f.isDirectory()) sb.append("/");
                    sb.append("\">" ).append(escapeHtml(name)).append("</a></li>");
                }
            }
        }
        sb.append("</ul></body></html>");
        Map<String, String> respHeaders = new HashMap<>();
        respHeaders.put("Content-Type", "text/html; charset=UTF-8");
        respHeaders.put("X-Content-Type-Options", "nosniff");
        return new ProxyResponse(200, sb.toString(), respHeaders);
    }

    private ProxyResponse serveFile(File file) {
        try {
            byte[] content = Files.readAllBytes(file.toPath());
            Map<String, String> respHeaders = new HashMap<>();
            respHeaders.put("Content-Type", detectContentType(file.getName()));
            respHeaders.put("X-Content-Type-Options", "nosniff");
            return new ProxyResponse(200, new String(content), respHeaders);
        } catch (IOException e) {
            return new ProxyResponse(500, "Internal Server Error", Collections.emptyMap());
        }
    }

    private String detectContentType(String filename) {
        if (filename.endsWith(".html")) return "text/html";
        if (filename.endsWith(".json")) return "application/json";
        if (filename.endsWith(".pem")) return "application/x-pem-file";
        return "application/octet-stream";
    }

    private boolean checkRateLimit(String clientIp) {
        long now = System.currentTimeMillis();
        Long lastRequest = rateLimitMap.get(clientIp);
        if (lastRequest != null && (now - lastRequest) < (RATE_LIMIT_WINDOW_MS / MAX_REQUESTS_PER_WINDOW)) {
            return false;
        }
        rateLimitMap.put(clientIp, now);
        return true;
    }

    private String escapeHtml(String input) {
        return input.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                    .replace("\"", "&quot;").replace("'", "&#x27;");
    }

    public static class ProxyResponse {
        public final int statusCode;
        public final String body;
        public final Map<String, String> headers;

        public ProxyResponse(int statusCode, String body, Map<String, String> headers) {
            this.statusCode = statusCode;
            this.body = body;
            this.headers = headers;
        }
    }
}
